/* B24 independent read-only diagnostics; every result set must be empty. */ /* Run all reconcile_*.sql within one REPEATABLE READ / READ ONLY transaction. */ SELECT `b`.`stock_item_id`, `b`.`location_id` FROM `stock_balance` AS `b` WHERE `b`.`on_hand` < 0 OR `b`.`reserved` < 0 OR `b`.`reserved` > `b`.`on_hand`;

/* serial_position must match the sole physical positive balance, including owner. */ /* serial_position must match the sole physical positive balance, including owner. */ SELECT COALESCE(`p`.`serial_id`, `i`.`serial_id`) AS `serial_id` FROM `serial_position` AS `p` LEFT JOIN (SELECT `si`.`serial_id`, `b`.`location_id`, `si`.`id` AS `stock_item_id` FROM `stock_balance` AS `b` JOIN `stock_item` AS `si` ON `si`.`id` = `b`.`stock_item_id` WHERE `si`.`serial_id` IS NOT NULL AND `b`.`on_hand` > 0) AS `i` ON `i`.`serial_id` = `p`.`serial_id` LEFT JOIN `stock_move` AS `last_move` ON `last_move`.`id` = `p`.`last_move_id` WHERE `p`.`serial_id` IS NULL OR `i`.`serial_id` IS NULL OR `p`.`location_id` <> `i`.`location_id` OR `last_move`.`stock_item_id` <> `i`.`stock_item_id` OR `last_move`.`destination_location_id` <> `p`.`location_id` UNION ALL /* serial_position must match the sole physical positive balance, including owner. */ SELECT COALESCE(`p`.`serial_id`, `i`.`serial_id`) AS `serial_id` FROM `serial_position` AS `p` RIGHT JOIN (SELECT `si`.`serial_id`, `b`.`location_id`, `si`.`id` AS `stock_item_id` FROM `stock_balance` AS `b` JOIN `stock_item` AS `si` ON `si`.`id` = `b`.`stock_item_id` WHERE `si`.`serial_id` IS NOT NULL AND `b`.`on_hand` > 0) AS `i` ON `i`.`serial_id` = `p`.`serial_id` LEFT JOIN `stock_move` AS `last_move` ON `last_move`.`id` = `p`.`last_move_id` WHERE (`p`.`serial_id` IS NULL OR `i`.`serial_id` IS NULL OR `p`.`location_id` <> `i`.`location_id` OR `last_move`.`stock_item_id` <> `i`.`stock_item_id` OR `last_move`.`destination_location_id` <> `p`.`location_id`) AND NOT EXISTS(SELECT 1 FROM `serial_position` AS `p` WHERE `i`.`serial_id` = `p`.`serial_id`);

/* Consumption tracing must agree with the reservation aggregate. */ SELECT `r`.`id` FROM `reservation` AS `r` LEFT JOIN `reservation_consumption` AS `c` ON `c`.`reservation_id` = `r`.`id` GROUP BY `r`.`id`, `r`.`consumed` HAVING `r`.`consumed` <> COALESCE(SUM(`c`.`quantity`), 0);

/* Each reversal preserves identity/quantity and exactly swaps both legs. */ SELECT `r`.`id` FROM `stock_move` AS `r` JOIN `stock_move` AS `s` ON `s`.`id` = `r`.`reverses_move_id` JOIN `inventory_transaction` AS `rt` ON `rt`.`id` = `r`.`transaction_id` WHERE `r`.`stock_item_id` <> `s`.`stock_item_id` OR `r`.`quantity_base` <> `s`.`quantity_base` OR `r`.`source_location_id` <> `s`.`destination_location_id` OR `r`.`destination_location_id` <> `s`.`source_location_id` OR `rt`.`reverses_transaction_id` <> `s`.`transaction_id`;

SELECT `t`.`id` FROM `inventory_transaction` AS `t` WHERE `t`.`reverses_transaction_id` IS NOT NULL AND (SELECT COUNT(*) AS `count` FROM `stock_move` AS `m` WHERE `m`.`transaction_id` = `t`.`id`) <> (SELECT COUNT(*) AS `count` FROM `stock_move` AS `m` WHERE `m`.`transaction_id` = `t`.`reverses_transaction_id`);

/* Posting must leave both an audit record and a versioned outbox event in the same transaction. */ SELECT `t`.`id` FROM `inventory_transaction` AS `t` WHERE NOT EXISTS(SELECT 1 FROM `audit_event` AS `a` WHERE `a`.`after_data` ->> '$.transaction_id' = CAST(`t`.`id` AS CHAR)) OR NOT EXISTS(SELECT 1 FROM `outbox_event` AS `e` WHERE `e`.`payload` ->> '$.transaction_id' = CAST(`t`.`id` AS CHAR));
